#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long modPow(long long base, long long exp, long long mod) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) {
            result = result * base % mod;
        }
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

long long modInverse(long long a, long long m) {
    return modPow(a, m - 2, m);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<vector<long long>> S(5005, vector<long long>(5005, 0));
    S[1][1] = 1;
    S[0][0] = 0;
    for (int i = 1; i <= 5000; i++) {
        S[i][i] = 1;
        S[i][0] = 0;
    }
    for (int i = 2; i <= 5000; i++) {
        for (int j = 1; j <= i; j++) {
            S[i][j] = (S[i - 1][j] * j % MOD + S[i - 1][j - 1]) % MOD;
        }
    }

    long long n, m;
    int k;
    cin >> n >> m >> k;
    m = modInverse(m, MOD);

    vector<long long> dp(5005, 0);
    dp[0] = 1;
    int limit = (int)std::min(n, (long long)k);
    for (int i = 1; i <= limit; i++) {
        dp[i] = dp[i - 1] * (n - i + 1) % MOD;
    }

    long long answer = 0;
    for (int i = 1; i <= limit; i++) {
        long long term = dp[i] * modPow(m, i, MOD) % MOD * S[k][i] % MOD;
        answer = (answer + term) % MOD;
    }

    cout << answer << "\n";

    return 0;
}
